const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && git status --short --branch && git remote -v && rg --files -g 'AGENTS.md' -g 'composer.json' -g 'composer.lock' -g '.github/workflows/**' -g '*phpunit*' -g '*phpstan*' -g '*renovate*'","max_output_tokens":7000}),
  tools.exec_command({cmd:"cat /Users/ab/.agents/skills/find-docs/SKILL.md","max_output_tokens":8000}),
  tools.exec_command({cmd:"gh auth status && gh repo view k-kinzal/php-ai-toolkit --json nameWithOwner,defaultBranchRef,url","max_output_tokens":4000})
]); results.forEach((r,i)=>text({i,...r}));

text(await tools.exec_command({cmd:"git fetch origin","max_output_tokens":4000}));
const results = await Promise.allSettled([
 tools.exec_command({cmd:"git status --short --branch && git log --oneline origin/main..main && cat AGENTS.md && rg --files --hidden .github && cat renovate.json","max_output_tokens":10000}),
 tools.exec_command({cmd:"gh run list --repo k-kinzal/php-ai-toolkit --branch main --limit 20 --json databaseId,workflowName,headSha,status,conclusion,url,createdAt && gh pr list --repo k-kinzal/php-ai-toolkit --state open --limit 100 --json number,title,author,headRefName,baseRefName,mergeable,mergeStateStatus,statusCheckRollup,url","max_output_tokens":16000})
]);results.forEach((r,i)=>text({i,...r}));

const results = await Promise.allSettled([
 tools.exec_command({cmd:"gh run view 37876980981 --repo k-kinzal/php-ai-toolkit --log-failed","max_output_tokens":13000}),
 tools.exec_command({cmd:"cat .github/workflows/mutation.yml && cat .github/workflows/ci.yml && rg --files --hidden -g '!**/vendor/**' -g '!**/.git/**' -g '!**/node_modules/**' -g '*infection*' -g '*Makefile*' -g '*.sh' -g 'AGENTS.md' && git diff --stat origin/main..main && php --version && composer --version","max_output_tokens":14000}),
 tools.exec_command({cmd:"cat packages/guard-php/composer.json && cat packages/docgen-php/composer.json && cat packages/phpstan-guard-rules/composer.json && rg --files -g '*README*' -g '*infection*' -g '!**/vendor/**'","max_output_tokens":8000})
]);results.forEach((r,i)=>text({i,...r}));

