        for ($position = 0; $position < count($queue); $position++) {
            $entries = scandir($queue[$position]);
            foreach ($entries === false ? [] : $entries as $entry) {
                if ($entry === '.' || $entry === '..') {
                    continue;
                }

                $path = $queue[$position] . '/' . $entry;
                if (is_dir($path)) {
                    $queue[] = $path;
                } elseif (str_ends_with($entry, '.xml') && $entry !== 'index.xml') {
