        if ($class === null) {
            return null;
        }

        $method = $node->name->toString();

        return [
            'key' => $this->ids->method($class->getName(), $method),
            'symbol' => $class->getName() . '::' . $method . '()',
            'line' => $node->getStartLine(),
        ];
    }

    /**
     * @return list<string>
