        $prototypes = [];
        foreach ($class->getAncestors() as $ancestor) {
            if ($ancestor->getName() !== $class->getName() && $ancestor->hasNativeMethod($method)) {
                $prototypes[] = $this->ids->method($ancestor->getName(), $method);
            }
        }

