    private MutationContractReader $reader;

    /**
     * Creates a declaration collector from syntax and identifier readers.
     */
    public function __construct(
        ?CallableId $ids = null,
        ?RulePhpDocParser $parser = null,
        ?MutationContractReader $reader = null,
    ) {
