     */
    public function identity(\PhpParser\Node $node, Scope $scope): ?array
    {
        if ($node instanceof \PhpParser\Node\Stmt\Function_) {
            $name = isset($node->namespacedName) ? $node->namespacedName->toString() : $node->name->toString();

